mapper.update:
UPDATE policy_document
SET status = 'PUBLISHED', version = version + 1, updated_at = #{now}
WHERE id = #{id} AND deleted = 0 AND status IN ('DRAFT', 'OFFLINE')

UPDATE policy_document
SET status = 'OFFLINE', version = version + 1, updated_at = #{now}
WHERE id = #{id} AND deleted = 0 AND status = 'PUBLISHED'

UPDATE policy_document
SET attachment_key = #{attachmentKey}, version = version + 1, updated_at = #{now}
WHERE id = #{id} AND deleted = 0
